ValidationRule.ValidationCode:
AD_InfoWindow.AD_Table_ID =
  (SELECT AD_Table_ID
  FROM AD_Table
  WHERE tablename=
    (SELECT SUBSTR(
      (SELECT columnname FROM ad_column WHERE ad_column_ID=@AD_Column_ID@
      ),1,
      (SELECT LENGTH(columnname) FROM ad_column WHERE ad_column_ID=@AD_Column_ID@
      )-3)
    FROM dual
    )
  OR tablename=
    (SELECT tablename
    FROM ad_table
    WHERE ad_table_ID=
      (SELECT AD_Table_ID
      FROM AD_Ref_Table
      WHERE AD_Reference_ID=
        (SELECT AD_Reference_Value_ID FROM Ad_Column WHERE AD_Column_ID=@AD_Column_ID@
        )
      )
    )
  )
